func:
flow.set('lastTx', { topic: msg.topic, at: Date.now() });
node.status({ text: 'TX ' + msg.topic });
node.send([msg, { payload: 'TX ' + msg.topic + ': ' + msg.payload.toString('hex').match(/../g).join(' ') }]);

const b = msg.payload;
const tx = flow.get('lastTx') || {};
const hex = b.toString('hex').match(/../g).join(' ');
let kind = 'unknown';
const sumOk = b.length > 1 && (b.slice(0, -1).reduce((a, x) => a + x, 0) & 0xFF) === b[b.length - 1];
if (b[0] === 0xEB && b[1] === 0x90) kind = 'V1.3 reply EB 90';
else if (b[0] === 0x55 && b[1] === 0xAA && b[2] === 0xEB && b[3] === 0x90) kind = 'JK02 frame type 0x' + b[4].toString(16).padStart(2, '0');
else if (b[0] === 0xAA && b[1] === 0x55 && b[2] === 0x90 && b[3] === 0xEB) kind = 'JK02 command/ready 0x' + b[4].toString(16).padStart(2, '0');
const ms = tx.at ? (Date.now() - tx.at) + ' ms after ' + tx.topic : '';
node.status({ text: b.length + ' B, ' + kind });
msg.payload = 'RX ' + b.length + ' bytes, ' + kind + ', checksum ' + (sumOk ? 'ok' : 'no') + (ms ? ', ' + ms : '') + ':\n' + hex;
return msg;
